import{_ as s,o as a,c as i,a3 as n}from"./chunks/framework.qCVWde4n.js";const k=JSON.parse('{"title":"Run nanoMuse yourself","description":"","frontmatter":{},"headers":[],"relativePath":"self-hosting.md","filePath":"self-hosting.md"}'),t={name:"self-hosting.md"};function o(h,e,d,r,l,p){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="run-nanomuse-yourself" tabindex="-1">Run nanoMuse yourself <a class="header-anchor" href="#run-nanomuse-yourself" aria-label="Permalink to &quot;Run nanoMuse yourself&quot;">​</a></h1><p>nanoMuse is one agent on your own devices, and nothing in it has to go through a server of ours. There are three ways to run it yourself, from the least work to the most. Most people want the first; a family or a small group that wants its own sign-in wants the second; the third is for the web app on a machine of your own.</p><table tabindex="0"><thead><tr><th></th><th>What you run</th><th>What it gives you</th></tr></thead><tbody><tr><td><a href="#1-no-server-your-own-key">1. No server, your own key</a></td><td>nothing</td><td>the apps talk to a model provider directly; the community relay is still used for sign-in and for the devices to find each other</td></tr><tr><td><a href="#2-your-own-relay">2. Your own relay</a></td><td>nanoMuse Cloud on a small VPS or a home server</td><td>your own accounts, sign-in codes, hub and conversation sync; nothing about your account touches nanomuse.cn</td></tr><tr><td><a href="#3-a-runtime-of-your-own-for-the-web-app">3. A runtime of your own</a></td><td>the Python runtime in Docker</td><td>the web app and the hands on a computer that is always on</td></tr></tbody></table><h2 id="_1-no-server-your-own-key" tabindex="-1">1. No server, your own key <a class="header-anchor" href="#_1-no-server-your-own-key" aria-label="Permalink to &quot;1. No server, your own key&quot;">​</a></h2><p>The free allowance on the community relay runs out. When it does, or before, put a key of your own in the app — Alibaba Model Studio (百炼) inside mainland China, OpenRouter or any OpenAI-compatible endpoint elsewhere — and the model requests go from your device to that provider; the relay only sees the sign-in and the hub frames between your devices. <a href="./own-key">own-key.md</a> has the steps for every app. Nothing to install, nothing to keep running.</p><h2 id="_2-your-own-relay" tabindex="-1">2. Your own relay <a class="header-anchor" href="#_2-your-own-relay" aria-label="Permalink to &quot;2. Your own relay&quot;">​</a></h2><p>nanoMuse Cloud is the relay behind nanomuse.cn: sign-in by e-mail or phone, the account&#39;s models through one OpenAI-compatible endpoint, the hub the devices meet on, conversation sync, a web console at <code>/app</code> and an admin page at <code>/app/admin/</code>. It is one Python service and one SQLite file, in this repository under <a href="https://github.com/nano-muse/nanoMuse/blob/main/cloud/README.md" target="_blank" rel="noreferrer"><code>cloud/</code></a>, and it runs the same on a server of yours.</p><h3 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h3><ul><li><strong>A machine.</strong> A VPS with 1 vCPU and 1 GB of memory is enough for a family; the relay idles at a few tens of megabytes and the model work happens at the provider. Such a server costs on the order of ¥30–60 a month inside mainland China or US$4–6 outside it, from any provider — the relay does not care which. A home server or a spare laptop works for a LAN-only relay.</li><li><strong>A domain</strong> pointing at the machine (an A record), with ports 80 and 443 reachable. Caddy, which runs next to the relay, fetches and renews the Let&#39;s Encrypt certificate on its own. Skip this for a LAN-only relay.</li><li><strong>A model provider key.</strong> The relay spends <em>your</em> money on <em>your</em> provider: everyone who signs in on your relay is billed to that key, at the provider&#39;s prices, within the allowance you set (<code>ALLOWANCE_CNY</code>, <code>SIGNUP_OPEN</code>, members in <code>ALLOWED_IDENTIFIERS</code> — <a href="https://github.com/nano-muse/nanoMuse/blob/main/cloud/README.md#settings" target="_blank" rel="noreferrer">cloud/README.md</a>). Without a key, sign-in and the hub work and chat does not.</li><li><strong>Docker</strong> with the compose plugin, and <code>curl</code>.</li></ul><h3 id="in-one-command" tabindex="-1">In one command <a class="header-anchor" href="#in-one-command" aria-label="Permalink to &quot;In one command&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/nano-muse/nanoMuse.git</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nanoMuse</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/self-host.sh</span></span></code></pre></div><p>The script asks five things — the domain (or <code>local</code>), an e-mail for Let&#39;s Encrypt, how sign-in codes go out, the provider&#39;s URL and key, the admin password — writes <code>cloud/.env</code> with a fresh random <code>CLOUD_SECRET</code>, starts <code>docker compose</code>, waits for <code>/healthz</code> and prints the console and admin URLs. Running it again keeps the secrets and the accounts and only re-asks, with the current values as defaults. For this machine only, no domain and no TLS:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/self-host.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --local</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # http://127.0.0.1:8787, codes in the relay&#39;s log</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/self-host.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --local</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bind</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.0.0.0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # reachable from the phones on the same network</span></span></code></pre></div><p>By hand instead of the script: <code>cd cloud &amp;&amp; cp .env.example .env</code>, fill in <code>CLOUD_DOMAIN</code>, <code>PUBLIC_BASE</code>, <code>ACME_EMAIL</code>, <code>CLOUD_SECRET</code>, <code>CLOUD_ADMIN_TOKEN</code>, <code>UPSTREAM_KEY</code> and the sender settings, then <code>docker compose up -d</code> — or, without Caddy, <code>docker compose -f docker-compose.yml -f docker-compose.local.yml up -d</code>.</p><h3 id="sign-in-codes" tabindex="-1">Sign-in codes <a class="header-anchor" href="#sign-in-codes" aria-label="Permalink to &quot;Sign-in codes&quot;">​</a></h3><p>A code goes out every time someone signs in. <code>CODE_SENDER</code> says how:</p><ul><li><code>log</code> — printed to the relay&#39;s log only: <code>cd cloud &amp;&amp; docker compose logs relay</code> shows <code>verification code for …</code>. Fine for a family: you read the code out. This is what <code>--local</code> uses.</li><li><code>smtp</code> — by e-mail through a mailbox you own (<code>SMTP_HOST</code>, <code>SMTP_PORT</code>, <code>SMTP_USER</code>, <code>SMTP_PASSWORD</code>, <code>SMTP_FROM</code>). Any mailbox with SMTP works; a free one is enough for a few people.</li><li><code>aliyun</code> — by SMS to mainland China numbers through Alibaba Cloud: 号码认证服务 by default (<code>ALIYUN_SMS_API=dypns</code>, its ready-made templates), or 短信服务 with a signed template of your own (<code>ALIYUN_SMS_API=dysms</code>); the variables are in <code>cloud/.env.example</code>. <code>both</code> uses SMTP for addresses and Aliyun for numbers. SMS reaches mainland numbers only; everyone else signs in by e-mail.</li></ul><h3 id="the-admin-page" tabindex="-1">The admin page <a class="header-anchor" href="#the-admin-page" aria-label="Permalink to &quot;The admin page&quot;">​</a></h3><p><code>https://&lt;your domain&gt;/app/admin/</code> with the admin password (<code>CLOUD_ADMIN_TOKEN</code> in <code>cloud/.env</code>): the accounts, what each has spent, allowance and membership, nudge policies, the devices on the hub, the relay&#39;s own health. The same data is behind <code>/v1/admin/*</code> for scripts (<a href="https://github.com/nano-muse/nanoMuse/blob/main/cloud/README.md#operating" target="_blank" rel="noreferrer">cloud/README.md</a>).</p><h3 id="pointing-the-apps-at-it" tabindex="-1">Pointing the apps at it <a class="header-anchor" href="#pointing-the-apps-at-it" aria-label="Permalink to &quot;Pointing the apps at it&quot;">​</a></h3><p>Every app signs in against <code>https://cloud.nanomuse.cn</code> unless you tell it otherwise. The devices of one account must all point at the same relay — the hub and the conversations live there.</p><ul><li><p><strong>Android</strong> (0.1.38). <em>Use a different server</em> under the sign-in form takes the relay&#39;s address; <em>Check</em> asks its <code>/healthz</code> and shows the version, <em>Use this server</em> keeps the address across launches. <code>https://</code> is required outside your own network; plain <code>http://</code> is accepted for a private address (<code>10.x</code>, <code>172.16–31.x</code>, <code>192.168.x</code>, <code>localhost</code>, a <code>.local</code> or <code>.ts.net</code> name). Settings → Account shows the server with <em>Change</em>, which signs the phone out first (<a href="./android">android.md</a>).</p></li><li><p><strong>iPhone / iPad.</strong> The same link on the sign-in sheet, with the same rules.</p></li><li><p><strong>nanoMuse Desktop.</strong> The relay is the <code>baseURL</code> of the plugin&#39;s cloud row. Add this to <code>cordis.patch.yml</code> in the desktop&#39;s profile — <code>~/.nanomuse/desktop/profiles/nanomuse/</code> (<code>%USERPROFILE%\\.nanomuse\\desktop\\profiles\\nanomuse\\</code> on Windows; <code>NANOMUSE_DESKTOP_HOME</code> moves it) — and restart the app:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">nanomuse-cloud</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">dsh-nanomuse/cloud</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    baseURL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://cloud.example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    deviceName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    statePath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&#39;</span></span></code></pre></div><p>Setting <code>NANOMUSE_CLOUD_URL=https://cloud.example.com</code> in the environment the app starts in does the same without editing the file (<a href="./desktop">desktop.md</a>).</p></li><li><p><strong>The terminal runtime and the hosted web app</strong> (<code>nanomuse …</code>, the root <code>docker-compose.yml</code>): <code>NANOMUSE_CLOUD_BASE_URL=https://cloud.example.com</code> in the environment or <code>.env</code>, or <code>[cloud] base_url</code> in <code>config/config.toml</code> (<a href="./configuration">configuration.md</a>).</p></li><li><p><strong>The web console</strong> is the relay&#39;s own <code>/app</code> — <code>https://&lt;your domain&gt;/app/</code> — and needs no pointing.</p></li></ul><p>Invitations from your relay link to its console (<code>INVITE_URL</code>, set by the script), so a friend you invite lands on your relay, not on nanomuse.cn.</p><h3 id="updating" tabindex="-1">Updating <a class="header-anchor" href="#updating" aria-label="Permalink to &quot;Updating&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nanoMuse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/self-host.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # Enter through the questions; secrets and accounts are kept</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or: cd cloud &amp;&amp; docker compose up -d --build</span></span></code></pre></div><p>The database schema migrates forward on start. Read the release notes before a jump of several versions; the relay&#39;s version is in <code>GET /healthz</code>.</p><h3 id="backing-up" tabindex="-1">Backing up <a class="header-anchor" href="#backing-up" aria-label="Permalink to &quot;Backing up&quot;">​</a></h3><p>Everything the relay keeps is <code>cloud/data/cloud.db</code> (SQLite) plus <code>CLOUD_SECRET</code> in <code>cloud/.env</code>. The database is useless without the secret (the identifiers are hashed and encrypted with it, and so is a sign-in code still waiting to be used, which is only six digits), and the secret is useless without the database; back them up together, and never rotate the secret unless you mean to start over:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cloud</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> relay</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sqlite3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /srv/nanomuse-cloud/data/cloud.db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;.backup /srv/nanomuse-cloud/data/backup.db&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ||</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/cloud.db</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data/backup.db</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # when the container has no sqlite3: stop the relay first for a clean copy</span></span></code></pre></div><p>Caddy&#39;s certificates live in the <code>caddy_data</code> volume and are fetched again if lost.</p><h3 id="what-your-relay-stores" tabindex="-1">What your relay stores <a class="header-anchor" href="#what-your-relay-stores" aria-label="Permalink to &quot;What your relay stores&quot;">​</a></h3><p>Hashed and encrypted identifiers, per-request counts and prices, the devices on the hub, and — only while <em>Sync conversations between my devices</em> is on — the text of the conversations so the other devices can show them. No files, no screenshots, no passwords. The full list, and what each switch does, is <a href="./privacy">privacy.md</a>; as the operator you are the one it now describes.</p><h2 id="_3-a-runtime-of-your-own-for-the-web-app" tabindex="-1">3. A runtime of your own, for the web app <a class="header-anchor" href="#_3-a-runtime-of-your-own-for-the-web-app" aria-label="Permalink to &quot;3. A runtime of your own, for the web app&quot;">​</a></h2><p>The phone and the desktop carry their own agent. The web app does not — it talks to the Python runtime, which on nanomuse.cn runs in a container per visitor. You can run that runtime on a machine of your own, in Docker, and open the web app on it from any browser:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; $EDITOR </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.env</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # a model key, NANOMUSE_SERVER_TOKEN; NANOMUSE_CLOUD_BASE_URL for your own relay</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nanomuse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                      # or copy config/config.example.toml to config/config.toml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # the web app on http://&lt;host&gt;:8787, the URL with its token in the logs</span></span></code></pre></div><p>The container sees only its data volume and <code>./workspace</code>; capabilities are dropped. Keeping it running, a published image for arm64, and reaching it from outside your network are in <a href="./deployment">deployment.md</a>. The runtime signs in to a relay like any other device — yours, from section 2, if you set <code>NANOMUSE_CLOUD_BASE_URL</code> — and then the phone can hand it tasks over the hub like a computer that is always on (<a href="./every-device">every-device.md</a>).</p>`,36)])])}const u=s(t,[["render",o]]);export{k as __pageData,u as default};
